const dialog=document.querySelector('#project-dialog');
projects.forEach((p,i)=>{const b=document.createElement('button');b.className='project';b.innerHTML=`<div class="project-image"><img loading="lazy" src="assets/${p.image}.webp" alt="${p.name} website"><span class="view-project" aria-hidden="true">↗</span></div><div class="project-info"><h3>${p.name}</h3><p>${p.category}</p><span>${String(i+1).padStart(2,'0')}</span></div>`;b.setAttribute('aria-label',`View ${p.name} project details`);b.onclick=()=>{document.querySelector('#dialog-img').src=`assets/${p.image}.webp`;document.querySelector('#dialog-img').alt=p.name+' website';document.querySelector('#dialog-title').textContent=p.name;document.querySelector('#dialog-category').textContent=p.category;document.querySelector('#dialog-description').textContent=p.description;dialog.showModal();document.body.style.overflow='hidden'};document.querySelector(i<4?'#featured':'#archive-grid').append(b)});
document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const journey=document.querySelector('.journey'),stage=document.querySelector('.stage'),left=document.querySelector('.gate-left'),right=document.querySelector('.gate-right'),hero=document.querySelector('.hero-copy'),reveal=document.querySelector('.reveal-copy'),portrait=document.querySelector('.portrait-wrap'),shade=document.querySelector('.shade'),motion=document.querySelector('#motion');let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const clamp=x=>Math.max(0,Math.min(1,x));let scheduled=false;
function render(){scheduled=false;const span=journey.offsetHeight-stage.offsetHeight;const p=clamp(-journey.getBoundingClientRect().top/span),open=reduced?(p>.3?1:0):clamp((p-.08)/.65),fade=clamp(p/.24),show=reduced?open:clamp((p-.35)/.32);left.style.transform=`perspective(1400px) translateX(${-open*102}%) rotateY(${-open*24}deg)`;right.style.transform=`perspective(1400px) translateX(${open*102}%) rotateY(${open*24}deg)`;hero.style.opacity=1-fade;hero.style.transform=`translateY(${-fade*35}px)`;hero.style.visibility=fade>=1?'hidden':'visible';reveal.style.opacity=show;reveal.style.visibility=show>0?'visible':'hidden';reveal.style.transform=`translateY(${(1-show)*30}px)`;portrait.style.opacity=show;portrait.style.transform=`translateY(${(1-show)*18}%) scale(${.78+show*.22})`;shade.style.opacity=1-open*.65;document.querySelector('#chapter').textContent=p>.48?'02 / BEHIND THE WORK':'01 / THE ENTRANCE';document.querySelector('.reading-progress').style.width=`${clamp(scrollY/(document.documentElement.scrollHeight-innerHeight))*100}%`}
function schedule(){if(!scheduled){scheduled=true;requestAnimationFrame(render)}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);function setMotion(){document.documentElement.classList.toggle('motion-off',reduced);motion.innerHTML=`Motion ${reduced?'off':'on'} <span>◉</span>`;motion.setAttribute('aria-pressed',String(reduced));motion.setAttribute('aria-label',reduced?'Enable animation':'Reduce animation');render()}motion.onclick=()=>{reduced=!reduced;setMotion()};setMotion();document.querySelector('#open-door').onclick=()=>window.scrollTo({top:journey.offsetTop+(journey.offsetHeight-stage.offsetHeight)*.85,behavior:reduced?'instant':'smooth'});
document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const subject='Project enquiry from '+d.get('name');const body=`Hi Usman,\n\n${d.get('brief')}\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}`;window.location.href=`mailto:usmanfar2002@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;document.querySelector('#form-note').textContent='Your brief is ready in your email app. Send it there, or email usmanfar2002@gmail.com directly.'});
